'use strict';
const POLOS=['PIB Batel','PIB Uberaba','PIB Boqueirão','PIB Piraquara','PIB Colombo','PIB Tamandaré','PIB Campo Largo','PIB Campo Comprido','PIB Portão','PIB Parolin'];
const REMOVIDOS=['Chácara Masculina','Chácara Feminina','Cristolândia Mandirituba','Cristolândia Portão','Jonnys House','Centro de Formação Batel'];
const CHECK=['Rotas de fuga verificadas','Extintores no lugar e dentro da validade','Iluminação de emergência funcionando','Saídas desobstruídas','Kit de primeiros socorros / DEA conferido','Comunicação por rádio testada'];
const TIPOS=['Atendimento médico / primeiros socorros','Princípio de incêndio','Conflito / perturbação','Criança perdida','Outro'];
const PLU={bc:'Bombeiros civis',seg:'Seguranças descaracterizados',bri:'Brigadistas profissionais'};
const FUN={bc:'Bombeiro civil',seg:'Segurança descaracterizado',bri:'Brigadista profissional'};
const DIAS=['domingo','segunda','terça','quarta','quinta','sexta','sábado'];
const MESES=['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];
const RESP='Antônio Neto e Equipe Operacional';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defModelo=()=>[{dia:5,hora:'19:30',nome:'Sexta noite'},{dia:6,hora:'19:30',nome:'Sábado noite'},{dia:0,hora:'10:00',nome:'Domingo manhã'},{dia:0,hora:'18:00',nome:'Domingo noite'}];
const VER='v12';const CFGK='bc-cultos-cfg';
// a chave 'cfg' é compartilhada com o app de Manutenção dos Polos (mesmo domínio github.io): só aproveita se for deste app
const F1='https://pibcuritiba.org.br/programacoes/',F2='https://pibcuritiba.org.br/aresposta/',F3='https://pibcuritiba.org.br/oneministerio/cultos/',FP='https://pibcuritiba.org.br/site-portao/',FU='https://pibcuritiba.org.br/congregacoes/uberaba/',FC='https://pibcuritiba.org.br/campocomprido/',FPA='https://pibcuritiba.org.br/oneministerio/congregacao/parolin/';
// horários levantados no site da PIB (pibcuritiba.org.br). Polos sem horário publicado ficam "a confirmar".
const SITEH={'PIB Batel':{fonte:F1,cultos:[{dia:5,hora:'19:30',nome:'One Flow (adolescentes) – Templo'},{dia:6,hora:'17:00',nome:'1º Culto One (jovens)'},{dia:6,hora:'19:30',nome:'2º Culto One (jovens)'},{dia:0,hora:'09:00',nome:'1º Culto – manhã'},{dia:0,hora:'11:00',nome:'2º Culto – manhã'},{dia:0,hora:'19:00',nome:'Culto – noite'}]},
'PIB Portão':{fonte:FP,cultos:[{dia:6,hora:'19:30',nome:'Culto One (juventude)'},{dia:0,hora:'10:00',nome:'Culto da Família – manhã'},{dia:0,hora:'19:00',nome:'Culto da Família – noite'}]},
'PIB Uberaba':{fonte:FU,cultos:[{dia:6,hora:'19:30',nome:'Culto Juventude One'},{dia:0,hora:'19:00',nome:'Culto da Família'}]},
'PIB Campo Comprido':{fonte:FC,cultos:[{dia:5,hora:'19:30',nome:'Culto dos adolescentes'},{dia:0,hora:'19:00',nome:'Culto'}]},
'PIB Parolin':{fonte:FPA,cultos:[{dia:0,hora:'17:00',nome:'Culto (todas as idades)'}]}};
function defPolos(){const r={};for(const p of POLOS){const s=SITEH[p];r[p]={ativo:p==='PIB Batel',confirmar:!s,fonte:s?s.fonte:'',cultos:s?s.cultos.map(x=>({...x})):[]}}return r}
const modelo=(so)=>{const r=[];for(const p of POLOS){const c=cfg.polos[p];if(!c||!c.ativo)continue;if(so&&so!==p)continue;for(const t of c.cultos)r.push({...t,polo:p})}for(const[p,c]of Object.entries(cfg.polos))if(!POLOS.includes(p)&&c.ativo&&(!so||so===p))for(const t of c.cultos)r.push({...t,polo:p});return r};
function normCfg(c){c=(c&&typeof c==='object')?c:{};const d=defPolos();const P=(c.polos&&typeof c.polos==='object')?c.polos:null;const out={};
for(const[p,v]of Object.entries(d)){const o=P&&P[p];out[p]=o&&typeof o==='object'?{ativo:!!o.ativo,confirmar:!!o.confirmar,fonte:o.fonte||v.fonte,cultos:Array.isArray(o.cultos)?o.cultos.filter(t=>t&&typeof t.dia==='number').map(t=>({dia:t.dia,hora:t.hora||'',nome:t.nome||'Culto'})):v.cultos}:v}
if(P)for(const[p,o]of Object.entries(P))if(!out[p]&&!REMOVIDOS.includes(p)&&o&&Array.isArray(o.cultos))out[p]={ativo:!!o.ativo,confirmar:!!o.confirmar,fonte:o.fonte||'',cultos:o.cultos.filter(t=>t&&typeof t.dia==='number')};
if(!P&&Array.isArray(c.modelo)&&JSON.stringify(c.modelo)!==JSON.stringify(defModelo())){const pp=out[c.polo]?c.polo:'PIB Batel';out[pp].ativo=true;out[pp].cultos=c.modelo.filter(t=>t&&typeof t.dia==='number').map(t=>({dia:t.dia,hora:t.hora||'19:30',nome:t.nome||'Culto'}))}
if(typeof c.polo!=='string'||!c.polo)c.polo='PIB Batel';if(!/^\d{4}-\d{2}$/.test(c.inicio||''))c.inicio=ymd(new Date()).slice(0,7);return{polos:out,polo:c.polo,inicio:c.inicio,filtro:typeof c.filtro==='string'?c.filtro:'',precos:(c.precos&&typeof c.precos==='object')?c.precos:undefined,sel:(c.sel&&typeof c.sel==='object')?c.sel:{},selD:(c.selD&&typeof c.selD==='object')?c.selD:null}}
let cfg=(()=>{let c=null;try{c=JSON.parse(localStorage.getItem(CFGK)||'null')}catch(e){}if(!c){try{const o=JSON.parse(localStorage.getItem('cfg')||'null');if(o&&(Array.isArray(o.modelo)||o.polos))c=o}catch(e){}}return normCfg(c)})();
function saveCfg(){cfg=normCfg(cfg);localStorage.setItem(CFGK,JSON.stringify(cfg))}saveCfg();
function ymd(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
const pd=s=>{const[a,b,c]=s.split('-').map(Number);return new Date(a,b-1,c||1)};
const fmt=s=>{const d=pd(s);return d.toLocaleDateString('pt-BR')+' ('+DIAS[d.getDay()]+')'};
const mesNome=m=>{const d=pd(m);return MESES[d.getMonth()]+' de '+d.getFullYear()};
const addMes=(m,n)=>{const d=pd(m);d.setMonth(d.getMonth()+n);return ymd(d).slice(0,7)};
const mesAtual=()=>ymd(new Date()).slice(0,7);
const mesesPiloto=()=>[0,1,2].map(i=>addMes(cfg.inicio,i));
const min=t=>{if(!t)return null;const[h,m]=t.split(':').map(Number);return h*60+m};
const horas=c=>{const a=min(c.checkin||(c.kind==='diaria'?c.hora:'')),b=min(c.checkout||(c.kind==='diaria'?c.horaFim:''));if(a==null||b==null)return 0;let d=b-a;if(d<0)d+=1440;return d/60};
const hfmt=h=>h.toFixed(1).replace('.',',')+' h';
// ---------- IndexedDB ----------
let dbp;function db(){return dbp||(dbp=new Promise((ok,er)=>{const r=indexedDB.open('bc-cultos',2);r.onupgradeneeded=()=>{for(const s of['equipe','cultos','midias','viaturas'])if(!r.result.objectStoreNames.contains(s))r.result.createObjectStore(s,{keyPath:'id'})};r.onsuccess=()=>ok(r.result);r.onerror=()=>er(r.error)}))}
async function tx(st,mode,fn){const d=await db();return new Promise((ok,er)=>{const t=d.transaction(st,mode);const r=fn(t.objectStore(st));t.oncomplete=()=>ok(r&&r.result);t.onerror=()=>er(t.error)})}
const arr=x=>Array.isArray(x)?x:[];
function normOc(o){o=o||{};return{tipo:o.tipo||'Outro',hora:o.hora||'',desc:o.desc||'',acao:o.acao||'',enc:o.enc||'',midias:arr(o.midias)}}
const NORM={cultos:c=>{if(!c)return c;c.data=c.data||'2000-01-01';c.hora=c.hora||'';c.nome=c.nome||'Culto';c.polo=c.polo||'PIB Batel';const b=arr(c.bc);c.bc=[b[0]||'',b[1]||''];c.seg=c.seg||'';c.bri=arr(c.bri);c.check=(c.check&&typeof c.check==='object')?c.check:{};c.ocorrencias=arr(c.ocorrencias).map(normOc);c.midias=arr(c.midias);c.obs=c.obs||'';c.checkin=c.checkin||'';c.checkout=c.checkout||'';c.amb=!!c.amb;c.viatura=c.viatura||'';return c},
equipe:p=>p&&Object.assign({funcao:'bc',tel:'',cert:'',validade:''},p,{nome:p.nome||'(sem nome)'}),viaturas:v=>v&&Object.assign({placa:'',tipo:'Ambulância de apoio',condutor:'',obs:''},v,{nome:v.nome||'(sem nome)'})};
const nrm=(st,v)=>NORM[st]?NORM[st](v):v;
const getAll=st=>tx(st,'readonly',s=>s.getAll()).then(l=>arr(l).filter(Boolean).map(v=>nrm(st,v)));const get=(st,k)=>tx(st,'readonly',s=>s.get(k)).then(v=>nrm(st,v));const put=(st,v)=>tx(st,'readwrite',s=>s.put(v));const del=(st,k)=>tx(st,'readwrite',s=>s.delete(k));
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,7);
// ---------- mídia ----------
function comprimir(file){return new Promise(ok=>{const img=new Image();img.onload=()=>{const m=1280,s=Math.min(1,m/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=img.width*s;c.height=img.height*s;c.getContext('2d').drawImage(img,0,0,c.width,c.height);c.toBlob(b=>ok(b),'image/jpeg',.72);URL.revokeObjectURL(img.src)};img.onerror=()=>ok(file);img.src=URL.createObjectURL(file)})}
const toDataURL=b=>new Promise(ok=>{const r=new FileReader();r.onload=()=>ok(r.result);r.readAsDataURL(b)});
async function thumbs(ids){let h='';for(const id of ids||[]){const m=await get('midias',id);if(!m)continue;const u=URL.createObjectURL(m.blob);h+=m.tipo.startsWith('video')?`<video src="${u}" controls></video>`:`<img src="${u}">`}return h}
// ---------- dados ----------
async function equipe(){return(await getAll('equipe')).sort((a,b)=>a.nome.localeCompare(b.nome))}
async function viaturas(){return(await getAll('viaturas')).sort((a,b)=>a.nome.localeCompare(b.nome))}
const mapV=async()=>Object.fromEntries((await viaturas()).map(v=>[v.id,v]));
const vNome=(V,id)=>V[id]?V[id].nome+(V[id].placa?' ('+V[id].placa+')':''):'viatura não definida';
async function diariasMes(m){return(await getAll('cultos')).filter(c=>c.kind==='diaria'&&c.data.startsWith(m)).sort((a,b)=>(a.data+a.hora)<(b.data+b.hora)?-1:1)}
async function cultosMes(m){return(await getAll('cultos')).filter(c=>c.kind!=='diaria'&&!REMOVIDOS.includes(c.polo)&&c.data.startsWith(m)).sort((a,b)=>(a.data+a.hora)<(b.data+b.hora)?-1:1)}
function novoCulto(data,hora,nome,polo){return{id:uid(),data,hora,nome:nome||'Culto',polo:polo||cfg.polo,bc:['',''],seg:'',bri:[],checkin:'',checkout:'',check:{},publico:'',ocorrencias:[],midias:[],obs:'',concluido:false}}
function datasModelo(m,so){const r=[];const d=pd(m+'-01');const mm=d.getMonth();const md=modelo(so);while(d.getMonth()===mm){for(const t of md)if(t.dia===d.getDay()&&t.hora)r.push({data:ymd(d),...t});d.setDate(d.getDate()+1)}return r}
const porSemana=so=>modelo(so).filter(t=>t.hora).length;const ativos=()=>Object.keys(cfg.polos).filter(p=>cfg.polos[p].ativo);const porMes=so=>porSemana(so)*4;
const completo=c=>c.bc[0]&&c.bc[1]&&c.seg&&c.bc[0]!==c.bc[1]&&(c.bri||[]).every(Boolean);
function faltas(c){const f=[];const n=c.bc.filter(Boolean).length;if(n<2)f.push((2-n)+' bombeiro(s) civil(is)');if(c.bc[0]&&c.bc[0]===c.bc[1])f.push('bombeiro repetido');if(!c.seg)f.push('segurança');const nb=(c.bri||[]).filter(x=>!x).length;if(nb)f.push(nb+' brigadista(s) não selecionado(s)');return f}
const status=c=>c.concluido?['concluida','Atendido']:completo(c)?['pendente','Escalado']:['atrasada','Escala incompleta'];
function validade(p){if(!p.validade)return'';const d=(pd(p.validade)-new Date())/864e5;return d<0?'<span class="st atrasada">Certificado vencido</span>':d<60?'<span class="st pendente">Vence em breve</span>':''}
// ---------- rotas ----------
const R={};window.addEventListener('hashchange',go);
async function go(){const[h,...a]=(location.hash.slice(1)||'painel').split('/');document.querySelectorAll('nav a').forEach(x=>x.classList.toggle('on',x.getAttribute('href')==='#'+h));window.scrollTo(0,0);try{await(R[h]||R.painel)(...a.map(decodeURIComponent))}catch(e){console.error(e);$('#app').innerHTML='<div class="card"><b>Erro ao abrir a tela.</b><p class="muted">'+esc(e.message)+'</p><button class="btn" onclick="location.reload()">Recarregar</button><button class="btn out" onclick="forcarAtualizacao()">🔄 Forçar atualização</button><p class="muted">Versão '+VER+'. Seus dados (cultos, equipe, fotos) não são apagados.</p></div>'}}
R.painel=async()=>{const m=mesAtual();const cs=await cultosMes(m);const eq=await equipe();const E=Object.fromEntries(eq.map(p=>[p.id,p]));
const at=cs.filter(c=>c.concluido),oc=cs.reduce((s,c)=>s+c.ocorrencias.length,0),inc=cs.filter(c=>!completo(c)).length,hs=at.reduce((s,c)=>s+horas(c),0);
const hoje=ymd(new Date());const prox=cs.filter(c=>c.data>=hoje&&!c.concluido).slice(0,6);
$('#app').innerHTML=`<h2>Painel – ${mesNome(m)}</h2><div class="grid"><div class="card kpi"><b>${at.length}/${cs.length}</b><small>cultos atendidos</small></div><div class="card kpi"><b>${hfmt(hs)}</b><small>horas de serviço</small></div><div class="card kpi"><b style="color:var(--red)">${oc}</b><small>ocorrências</small></div><div class="card kpi"><b style="color:${inc?'var(--red)':'var(--ok)'}">${inc}</b><small>escalas incompletas</small></div></div>
<p class="muted">Cada culto: 2 bombeiros civis + 1 segurança descaracterizado + brigadistas profissionais conforme necessidade · Equipe cadastrada: ${eq.filter(p=>p.funcao==='bc').length} BC, ${eq.filter(p=>p.funcao==='seg').length} seg., ${eq.filter(p=>p.funcao==='bri').length} brigadista(s)</p>
<h3>Próximos cultos</h3>${prox.length?prox.map(c=>cardCulto(c,E)).join(''):`<div class="card muted">Nenhum culto escalado. Vá em <a href="#escala">Escala</a> e gere os cultos do mês.</div>`}`};
function cardCulto(c,E){const[s,t]=status(c);const nm=id=>E[id]?esc(E[id].nome):'—';return`<a class="card" style="display:block;text-decoration:none;color:inherit" href="#culto/${c.id}"><div class="polo"><div><b>${esc(c.nome)} – ${fmt(c.data)} ${c.hora}</b><div class="muted">${esc(c.polo)}<br>BC: ${nm(c.bc[0])}, ${nm(c.bc[1])} · Seg.: ${nm(c.seg)}${(c.bri||[]).length?' · Brig.: '+c.bri.map(nm).join(', '):''}${c.amb?' · 🚑 Ambulância de apoio':''}${c.ocorrencias.length?' · Ocorrências: <b style="color:var(--red)">'+c.ocorrencias.length+'</b>':''}</div></div><span class="st ${s}">${t}</span></div></a>`}
// ---------- equipe ----------
R.equipe=async(id)=>{const eq=await equipe();const p=eq.find(x=>x.id===id)||{id:'',nome:'',funcao:'bc',tel:'',cert:'',validade:''};
$('#app').innerHTML=`<h2>Equipe</h2><a class="btn gold" href="#viaturas">🚑 Viaturas (Ambulância de apoio)</a><div class="card"><b>${p.id?'Editar profissional':'Novo profissional'}</b><br><label>Nome</label><input id="pNome" value="${esc(p.nome)}"><label>Função</label><select id="pFun">${Object.entries(FUN).map(([k,v])=>`<option value="${k}" ${p.funcao===k?'selected':''}>${v}</option>`).join('')}</select><label>Telefone</label><input id="pTel" type="tel" value="${esc(p.tel)}"><label>Nº do certificado / registro</label><input id="pCert" value="${esc(p.cert)}"><label>Validade do certificado</label><input id="pVal" type="date" value="${esc(p.validade)}"><button class="btn" onclick="salvarPro('${p.id}')">Salvar profissional</button>${p.id?`<button class="btn out" onclick="if(confirm('Remover este profissional?')){del('equipe','${p.id}').then(()=>location.hash='#equipe')}">Remover</button>`:''}</div>
${['bc','seg','bri'].map(f=>`<h3>${PLU[f]} (${eq.filter(x=>x.funcao===f).length})</h3>`+eq.filter(x=>x.funcao===f).map(x=>`<a class="card polo" style="text-decoration:none;color:inherit" href="#equipe/${x.id}"><div><b>${esc(x.nome)}</b><div class="muted">${esc(x.tel)||'—'} · Reg.: ${esc(x.cert)||'—'} · Validade: ${x.validade?pd(x.validade).toLocaleDateString('pt-BR'):'—'}</div></div>${validade(x)}</a>`).join('')).join('')}`};
window.salvarPro=async id=>{const nome=$('#pNome').value.trim();if(!nome)return alert('Informe o nome.');await put('equipe',{id:id||uid(),nome,funcao:$('#pFun').value,tel:$('#pTel').value,cert:$('#pCert').value,validade:$('#pVal').value});location.hash='#equipe';go()};
// ---------- escala ----------
R.escala=async(m)=>{m=m||mesAtual();const cs=await cultosMes(m);const eq=await equipe();const bcs=eq.filter(p=>p.funcao==='bc'),sgs=eq.filter(p=>p.funcao==='seg'),brs=eq.filter(p=>p.funcao==='bri');const vts=await viaturas();const opV=v=>'<option value="">— selecione a viatura —</option>'+vts.map(x=>`<option value="${x.id}" ${x.id===v?'selected':''}>${esc(x.nome)}${x.placa?' – '+esc(x.placa):''}</option>`).join('');
const op=(l,v)=>'<option value="">— selecione —</option>'+l.map(p=>`<option value="${p.id}" ${p.id===v?'selected':''}>${esc(p.nome)}</option>`).join('');
const polos=v=>POLOS.map(p=>`<option ${p===v?'selected':''}>${p}</option>`).join('')+(POLOS.includes(v)?'':`<option selected>${esc(v)}</option>`);
const rows=cs.map(c=>{const f=faltas(c);const[s,t]=status(c);return`<div class="card"${c.avulso?' style="border-left:6px solid var(--gold)"':''}>${c.avulso?'<span class="ex">⭐ EVENTO AVULSO</span>':''}<div class="polo"><b>${esc(c.nome)} – ${fmt(c.data)} ${c.hora}</b><span class="st ${s}">${t}</span></div>
<div class="row2"><input type="date" value="${c.data}" onchange="setC('${c.id}','data',this.value)"><input type="time" value="${c.hora}" onchange="setC('${c.id}','hora',this.value)"></div>
<label class="muted">Polo / local</label><input list="lpolos" value="${esc(c.polo)}" onchange="setC('${c.id}','polo',this.value)">
<label class="muted">Bombeiro civil 1</label><select onchange="setBC('${c.id}',0,this.value)">${op(bcs,c.bc[0])}</select><label class="muted">Bombeiro civil 2</label><select onchange="setBC('${c.id}',1,this.value)">${op(bcs,c.bc[1])}</select><label class="muted">Segurança descaracterizado</label><select onchange="setC('${c.id}','seg',this.value)">${op(sgs,c.seg)}</select><label class="muted">Brigadistas profissionais (opcional)</label><select onchange="setNB('${c.id}',+this.value)">${[0,1,2,3,4,5,6].map(n=>`<option value="${n}" ${(c.bri||[]).length===n?'selected':''}>${n} brigadista(s)</option>`).join('')}</select>${(c.bri||[]).map((v,j)=>`<label class="muted">Brigadista profissional ${j+1}</label><select onchange="setBR('${c.id}',${j},this.value)">${op(brs,v)}</select>`).join('')}<label class="chk"><input type="checkbox" ${c.amb?'checked':''} onchange="setC('${c.id}','amb',this.checked)">🚑 Ambulância de apoio (opcional)</label>${c.amb?`<select onchange="setC('${c.id}','viatura',this.value)">${opV(c.viatura)}</select>${vts.length?'':'<div class="muted">Cadastre a viatura em Equipe › Viaturas.</div>'}`:''}${f.length?`<div class="warn">⚠ Escala incompleta: falta ${f.join(', ')}</div>`:`<div class="okb">✔ Escala completa (2 BC + 1 segurança${(c.bri||[]).length?' + '+c.bri.length+' brigadista(s)':''})</div>`}
<a class="btn sec" href="#culto/${c.id}">${c.concluido?'Ver registro':'Abrir registro do culto'}</a><button class="btn out" onclick="if(confirm('Excluir este culto?')){del('cultos','${c.id}').then(go)}">Excluir culto</button></div>`}).join('');
$('#app').innerHTML=`<h2>Escala</h2><a class="btn gold" href="#diarias/${m}">🚑 Diárias de ambulância</a><datalist id="lpolos">${POLOS.map(p=>`<option value="${p}">`).join('')}</datalist><div class="grid">${m>mesAtual()?`<a class="btn out" href="#escala/${addMes(m,-1)}">◀ Anterior</a>`:'<span></span>'}${m<LIM.slice(0,7)?`<a class="btn out" href="#escala/${addMes(m,1)}">Próximo ▶</a>`:'<span></span>'}</div><h3>${mesNome(m)} – ${cs.length} culto(s)</h3>
${eq.length?'':'<div class="warn">Cadastre a equipe primeiro na aba Equipe.</div>'}
<button class="btn" onclick="gerarMes('${m}')">➕ Gerar cultos do mês (polos atendidos)</button>
${calHTML(m,cs)}<button class="btn sec" onclick="gerarAte()">📆 Gerar cultos até 30/01/2027</button><div class="card" id="fAvulso"><b>⭐ Evento avulso</b><p class="muted">Toque em uma data do calendário ou preencha abaixo.</p><div class="row2"><input type="date" id="nData" value="${m}-01"><input type="time" id="nHora" value="19:30"></div><input id="nNome" placeholder="Nome do evento (ex.: Conferência, culto especial)"><input list="lpolos" id="nPolo" value="${esc(cfg.polo)}" placeholder="Polo ou local (texto livre)"><label class="chk"><input type="checkbox" id="nAmb">🚑 Ambulância de apoio</label><p class="muted">A equipe (bombeiros, segurança, brigadistas) é escolhida no card do evento, abaixo, depois de adicionar.</p><button class="btn gold" onclick="avulso()">Adicionar evento avulso</button></div>${rows}
<h3>Polos atendidos e horários dos cultos</h3><p class="muted">Marque os polos atendidos. Horários levantados no site da PIB (pibcuritiba.org.br); todos editáveis. "Horário a confirmar" = não publicado no site.</p>${Object.keys(cfg.polos).map(p=>{const c=cfg.polos[p];const k=esc(p).replace(/'/g,"\\'");return`<div class="card" style="${c.ativo?'border-left:6px solid var(--ok)':''}"><label class="chk" style="border:0"><input type="checkbox" ${c.ativo?'checked':''} onchange="setPolo('${k}','ativo',this.checked)"><b>${esc(p)}</b></label>${c.confirmar?'<div class="warn">⚠ Horário a confirmar</div>':''}${c.fonte?`<div class="muted">Fonte: <a href="${esc(c.fonte)}" target="_blank" rel="noopener">${esc(c.fonte.replace('https://',''))}</a></div>`:''}
${c.cultos.map((t,i)=>`<div class="row2"><input value="${esc(t.nome)}" onchange="setCul('${k}',${i},'nome',this.value)"><select onchange="setCul('${k}',${i},'dia',+this.value)">${[5,6,0,1,2,3,4].map(n=>`<option value="${n}" ${t.dia===n?'selected':''}>${DIAS[n]}</option>`).join('')}</select></div><div class="row2"><input type="time" value="${t.hora}" onchange="setCul('${k}',${i},'hora',this.value)"><button class="btn out" style="margin:4px 0 8px;padding:10px" onclick="cfg.polos['${k}'].cultos.splice(${i},1);saveCfg();go()">Remover</button></div>`).join('')}
<button class="btn out" onclick="cfg.polos['${k}'].cultos.push({dia:0,hora:'19:00',nome:'Culto'});saveCfg();go()">+ Adicionar horário</button>${c.confirmar?`<button class="btn out" onclick="setPolo('${k}','confirmar',false)">✔ Marcar horários como confirmados</button>`:''}<div class="muted">${porSemana(p)} culto(s)/semana · ~${porMes(p)}/mês</div></div>`}).join('')}
<div class="card"><label class="muted">Polo padrão (eventos avulsos)</label><select onchange="cfg.polo=this.value;saveCfg()">${polos(cfg.polo)}</select><button class="btn out" onclick="if(confirm('Voltar aos horários do site para todos os polos? (polos atendidos voltam a: só PIB Batel)')){cfg.polos=defPolos();saveCfg();go()}">Restaurar horários do site</button></div>`};
window.setPolo=(p,k,v)=>{cfg.polos[p][k]=v;saveCfg();go()};window.setCul=(p,i,k,v)=>{cfg.polos[p].cultos[i][k]=v;saveCfg();go()};
window.gerarMes=async m=>{const cs=await cultosMes(m);let n=0;for(const t of datasModelo(m)){if(cs.some(c=>c.data===t.data&&c.hora===t.hora&&c.polo===t.polo))continue;await put('cultos',novoCulto(t.data,t.hora,t.nome,t.polo));n++}alert(n+' culto(s) criado(s).');go()};
window.avulso=async()=>{const d=$('#nData').value;if(!d)return;const c=novoCulto(d,$('#nHora').value,$('#nNome').value||'Evento avulso',$('#nPolo').value||cfg.polo);c.avulso=true;c.amb=$('#nAmb').checked;await put('cultos',c);location.hash='#escala/'+d.slice(0,7);go()};
const LIM='2027-01-30';
function calHTML(m,cs){const F=cfg.filtro;if(F)cs=cs.filter(c=>c.polo===F);const d0=pd(m+'-01');const n=new Date(d0.getFullYear(),d0.getMonth()+1,0).getDate();const dias=new Set(modelo(F).filter(t=>t.hora).map(t=>t.dia));const hoje=ymd(new Date());let h='';
for(let i=0;i<d0.getDay();i++)h+='<span></span>';
for(let k=1;k<=n;k++){const ds=m+'-'+String(k).padStart(2,'0');const dw=pd(ds).getDay();const cc=cs.filter(c=>c.data===ds);const ev=cc.some(c=>c.avulso);const cu=cc.some(c=>!c.avulso);
const cls=[ev?'cev':'',cu?'ccu':dias.has(dw)?'cmod':'',ds===hoje?'chj':'',ds>LIM?'cfora':''].join(' ');h+=`<button class="${cls}" onclick="tocarDia('${ds}')">${k}${cc.length?`<i>${cc.length}</i>`:''}</button>`}
return`<div class="card cal"><label class="muted">Filtrar calendário por polo</label><select onchange="cfg.filtro=this.value;saveCfg();go()"><option value="">Todos os polos atendidos</option>${Object.keys(cfg.polos).map(p=>`<option ${F===p?'selected':''} value="${esc(p)}">${esc(p)}${cfg.polos[p].ativo?'':' (não atendido)'}</option>`).join('')}</select><div class="cgrid chead">${['D','S','T','Q','Q','S','S'].map(x=>`<span>${x}</span>`).join('')}</div><div class="cgrid">${h}</div><div class="cleg"><span><i class="lg ccu"></i>Culto escalado</span><span><i class="lg cmod"></i>Dia de culto (modelo)</span><span><i class="lg cev"></i>Evento avulso</span></div></div>`}
window.tocarDia=ds=>{const f=$('#fAvulso');if(!f)return;$('#nData').value=ds;f.scrollIntoView({behavior:'smooth',block:'center'});f.classList.add('pisca');setTimeout(()=>f.classList.remove('pisca'),1200);$('#nNome').focus()};
window.gerarAte=async()=>{let m=mesAtual(),n=0;const todos=await getAll('cultos');while(m<=LIM.slice(0,7)){for(const t of datasModelo(m)){if(t.data>LIM||t.data<ymd(new Date()))continue;if(todos.some(c=>c.kind!=='diaria'&&c.data===t.data&&c.hora===t.hora&&c.polo===t.polo))continue;await put('cultos',novoCulto(t.data,t.hora,t.nome,t.polo));n++}m=addMes(m,1)}alert(n+' culto(s) criado(s) até 30/01/2027.');go()};
window.setC=async(id,k,v)=>{const c=await get('cultos',id);c[k]=v;await put('cultos',c);go()};
window.setNB=async(id,n)=>{const c=await get('cultos',id);c.bri=c.bri||[];while(c.bri.length<n)c.bri.push('');c.bri.length=n;await put('cultos',c);go()};
window.setBR=async(id,i,v)=>{const c=await get('cultos',id);c.bri[i]=v;await put('cultos',c);go()};
window.setBC=async(id,i,v)=>{const c=await get('cultos',id);c.bc[i]=v;await put('cultos',c);go()};
// ---------- registro do culto ----------
let C0=null;
R.culto=async(id)=>{C0=await get('cultos',id);if(!C0){location.hash='#escala';return}const DI=C0.kind==='diaria';const VV=await mapV();const E=Object.fromEntries((await equipe()).map(p=>[p.id,p]));const nm=i=>E[i]?esc(E[i].nome):'—';const f=faltas(C0);
let oc='';for(const[i,o]of C0.ocorrencias.entries())oc+=`<div class="card" data-i="${i}"><b>Ocorrência ${i+1}</b><label class="muted">Tipo</label><select onchange="setO(this,'tipo',this.value)">${TIPOS.map(t=>`<option ${o.tipo===t?'selected':''}>${t}</option>`).join('')}</select><label class="muted">Hora</label><input type="time" value="${o.hora}" onchange="setO(this,'hora',this.value)"><textarea rows="2" placeholder="Descrição" oninput="setO(this,'desc',this.value)">${esc(o.desc)}</textarea><textarea rows="2" placeholder="Ação tomada" oninput="setO(this,'acao',this.value)">${esc(o.acao)}</textarea><input placeholder="Encaminhamento (ex.: SAMU, família, liderança, sem encaminhamento)" value="${esc(o.enc)}" oninput="setO(this,'enc',this.value)"><label class="file">📷 Foto<input type="file" accept="image/*" capture="environment" multiple onchange="anexar(this,${i})"></label><label class="file">🎥 Vídeo<input type="file" accept="video/*" capture="environment" onchange="anexar(this,${i})"></label><div class="thumbs">${await thumbs(o.midias)}</div><button class="btn out" onclick="if(confirm('Remover ocorrência?')){C0.ocorrencias.splice(${i},1);put('cultos',C0).then(go)}">Remover ocorrência</button></div>`;
$('#app').innerHTML=DI?`<h2>Diária de ambulância – ${esc(C0.nome)}</h2><div class="card"><b>${fmt(C0.data)} ${C0.hora}–${C0.horaFim||'?'} · ${esc(C0.polo)}</b><div class="muted">🚑 Viatura: ${esc(vNome(VV,C0.viatura))}<br>Equipe: ${esc(C0.equipeTxt)||'—'}</div><a class="btn out" href="#diarias/${C0.data.slice(0,7)}">Alterar diária</a></div>`+await REST():`<h2>Registro – ${esc(C0.nome)}</h2><div class="card"><b>${fmt(C0.data)} ${C0.hora} · ${esc(C0.polo)}</b><div class="muted">Bombeiros civis: ${nm(C0.bc[0])}, ${nm(C0.bc[1])}<br>Segurança descaracterizado: ${nm(C0.seg)}${(C0.bri||[]).length?'<br>Brigadistas profissionais: '+C0.bri.map(nm).join(', '):''}</div>${f.length?`<div class="warn">⚠ Escala incompleta: falta ${f.join(', ')}</div>`:''}${C0.amb?'<div class="okb">🚑 Ambulância de apoio: '+esc(vNome(VV,C0.viatura))+'</div>':''}<a class="btn out" href="#escala/${C0.data.slice(0,7)}">Alterar escala</a></div>`+await REST();async function REST(){return`
<h3>Presença da equipe</h3><div class="card"><div class="row2"><div><label class="muted">Check-in</label><input type="time" id="cin" value="${C0.checkin}" onchange="C0.checkin=this.value;salvar()"></div><div><label class="muted">Check-out</label><input type="time" id="cout" value="${C0.checkout}" onchange="C0.checkout=this.value;salvar()"></div></div><div class="row2"><button class="btn sec" onclick="agora('checkin')">Check-in agora</button><button class="btn sec" onclick="agora('checkout')">Check-out agora</button></div>${DI?'':`<label class="muted">Público estimado</label><input type="number" id="pub" value="${esc(C0.publico)}" oninput="C0.publico=this.value;salvar()">`}</div>
${DI?'':`<h3>Checklist pré-culto</h3><div class="card">${CHECK.map((k,i)=>`<label class="chk"><input type="checkbox" ${C0.check[k]?'checked':''} onchange="C0.check[CHECK[${i}]]=this.checked;salvar()">${k}</label>`).join('')}</div>`}
<h3>Ocorrências (${C0.ocorrencias.length})</h3>${oc||'<div class="card muted">Nenhuma ocorrência registrada.</div>'}<button class="btn gold" onclick="novaOc()">➕ Registrar ocorrência</button>
<h3>Fotos e vídeos ${DI?'da diária':'do culto'}</h3><div class="card"><label class="file">📷 Foto<input type="file" accept="image/*" capture="environment" multiple onchange="anexar(this,-1)"></label><label class="file">🎥 Vídeo<input type="file" accept="video/*" capture="environment" onchange="anexar(this,-1)"></label><div class="thumbs">${await thumbs(C0.midias)}</div><textarea rows="3" placeholder="Observações gerais" oninput="C0.obs=this.value;salvar()">${esc(C0.obs)}</textarea></div>
<button class="btn" id="concluir" onclick="concluir()">✔ ${C0.concluido?'Atendimento concluído (salvar)':'Concluir atendimento'}</button><button class="btn sec" onclick="pdfCulto(C0)">📄 Relatório ${DI?'da diária':'do culto'} (PDF)</button>`}};
let tS;window.salvar=()=>{clearTimeout(tS);tS=setTimeout(()=>put('cultos',C0),300)};
window.setO=(el,k,v)=>{C0.ocorrencias[+el.closest('[data-i]').dataset.i][k]=v;salvar()};
window.agora=k=>{const d=new Date();C0[k]=String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');put('cultos',C0).then(go)};
window.novaOc=async()=>{const d=new Date();C0.ocorrencias.push({tipo:TIPOS[0],hora:String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0'),desc:'',acao:'',enc:'',midias:[]});await put('cultos',C0);go()};
window.anexar=async(inp,i)=>{for(const f of inp.files){let b=f;if(f.type.startsWith('image'))b=await comprimir(f);const id=uid();await put('midias',{id,blob:b,tipo:b.type||f.type,nome:f.name,quando:new Date().toISOString()});(i<0?C0.midias:C0.ocorrencias[i].midias).push(id)}await put('cultos',C0);go()};
window.concluir=async()=>{const p=[];if(!C0.checkin||!C0.checkout)p.push('check-in/check-out');if(C0.kind!=='diaria'){const nc=CHECK.filter(k=>!C0.check[k]).length;if(nc)p.push(nc+' item(ns) do checklist');if(!completo(C0))p.push('escala incompleta')}if(p.length&&!confirm('Pendente: '+p.join(', ')+'. Concluir mesmo assim?'))return;C0.concluido=true;C0.fim=new Date().toISOString();await put('cultos',C0);alert('Atendimento concluído e salvo neste aparelho.');go()};
// ---------- PDF ----------
const NAVY=[11,31,58],RED=[200,16,46],GOLD=[224,165,38];
function pdfBase(t,s){const doc=new jspdf.jsPDF({unit:'mm',format:'a4'});doc._t=t;doc._s=s;cab(doc);return doc}
function cab(doc){doc.setFillColor(...NAVY);doc.rect(0,0,210,24,'F');doc.setFillColor(...RED);doc.rect(0,24,210,2,'F');doc.setTextColor(255);doc.setFontSize(14);doc.setFont('helvetica','bold');doc.text('NR Treinamentos e Assessoria – '+doc._t,12,11);doc.setFontSize(9);doc.setFont('helvetica','normal');doc.setTextColor(...GOLD);doc.text(doc._s,12,18);doc._y=34}
function esp(doc,h){if(doc._y+h>282){doc.addPage();cab(doc)}}
function linha(doc,txt,o={}){const sz=o.size||10;doc.setFontSize(sz);doc.setFont('helvetica',o.bold?'bold':'normal');doc.setTextColor(...(o.cor||[30,30,30]));const l=doc.splitTextToSize(String(txt),o.w||186);esp(doc,l.length*sz*.42+1);doc.text(l,o.x||12,doc._y);doc._y+=l.length*sz*.42+1.5}
function secao(doc,t){esp(doc,12);doc._y+=2;doc.setFillColor(...GOLD);doc.rect(12,doc._y-4.5,2,6,'F');linha(doc,t,{bold:true,size:12,cor:NAVY,x:16})}
function rodape(doc){const n=doc.getNumberOfPages();for(let i=1;i<=n;i++){doc.setPage(i);doc.setFontSize(8);doc.setTextColor(120);doc.text('Responsável: '+RESP+' · Gerado em '+new Date().toLocaleString('pt-BR')+' · página '+i+'/'+n,12,292)}}
async function fotos(doc,ids){const ims=[];let vid=0;for(const id of ids||[]){const m=await get('midias',id);if(!m)continue;if(m.tipo.startsWith('image'))ims.push(m);else vid++}if(ims.length){esp(doc,32);let x=16;for(const m of ims.slice(0,5)){try{doc.addImage(await toDataURL(m.blob),'JPEG',x,doc._y,36,27)}catch(e){}x+=38}doc._y+=30}if(vid)linha(doc,vid+' vídeo(s) anexado(s) – disponíveis no aplicativo/backup',{size:9,cor:NAVY,x:16})}
async function corpoCulto(doc,c,E){const nm=i=>E[i]?E[i].nome+(E[i].cert?' (reg. '+E[i].cert+')':''):'—';const VV=await mapV();
if(c.kind==='diaria'){linha(doc,`Diária de ambulância – ${c.nome}`,{bold:true,size:12,cor:NAVY});linha(doc,`Data: ${fmt(c.data)}   Horário: ${c.hora} às ${c.horaFim||'—'}   Local/evento: ${c.polo}`);linha(doc,`Check-in: ${c.checkin||'—'}   Check-out: ${c.checkout||'—'}   Horas: ${hfmt(horas(c))}   Situação: ${c.concluido?'Realizada':'Em aberto'}`);secao(doc,'VIATURA E EQUIPE');linha(doc,'Ambulância de apoio: '+vNome(VV,c.viatura));linha(doc,'Equipe: '+(c.equipeTxt||'—'))}else{
linha(doc,`${c.nome} – ${fmt(c.data)} ${c.hora}`,{bold:true,size:12,cor:NAVY});linha(doc,'Local: '+c.polo+'    Público estimado: '+(c.publico||'—'));
linha(doc,`Check-in: ${c.checkin||'—'}   Check-out: ${c.checkout||'—'}   Horas: ${hfmt(horas(c))}   Situação: ${c.concluido?'Atendido':'Em aberto'}`);
secao(doc,'EQUIPE');linha(doc,'Bombeiro civil 1: '+nm(c.bc[0]));linha(doc,'Bombeiro civil 2: '+nm(c.bc[1]));linha(doc,'Segurança descaracterizado: '+nm(c.seg));(c.bri||[]).forEach((b,j)=>linha(doc,'Brigadista profissional '+(j+1)+': '+nm(b)));linha(doc,'Ambulância de apoio: '+(c.amb?vNome(VV,c.viatura):'não contratada'));if(!completo(c))linha(doc,'Escala incompleta: falta '+faltas(c).join(', '),{bold:true,cor:RED});
secao(doc,'CHECKLIST PRÉ-CULTO');for(const k of CHECK){esp(doc,6);doc.setFont('helvetica','bold');doc.setFontSize(10);doc.setTextColor(...(c.check[k]?[30,142,62]:RED));doc.text(c.check[k]?'OK':'NÃO VERIFICADO',150,doc._y);linha(doc,k,{w:130})}}
secao(doc,'OCORRÊNCIAS ('+c.ocorrencias.length+')');if(!c.ocorrencias.length)linha(doc,'Nenhuma ocorrência registrada.',{cor:[90,90,90]});
for(const[i,o]of c.ocorrencias.entries()){linha(doc,`${i+1}. ${o.hora} – ${o.tipo}`,{bold:true,cor:RED});if(o.desc)linha(doc,'Descrição: '+o.desc,{x:16,w:180});if(o.acao)linha(doc,'Ação tomada: '+o.acao,{x:16,w:180});linha(doc,'Encaminhamento: '+(o.enc||'—'),{x:16,w:180});await fotos(doc,o.midias)}
if(c.midias.length||c.obs){secao(doc,'REGISTROS GERAIS');if(c.obs)linha(doc,c.obs);await fotos(doc,c.midias)}}
async function compartilhar(doc,nome){const blob=doc.output('blob');window._ultimoPDF=blob;const f=new File([blob],nome,{type:'application/pdf'});
if(navigator.canShare&&navigator.canShare({files:[f]})){try{await navigator.share({files:[f],title:nome,text:'Relatório da NR Treinamentos e Assessoria'});return}catch(e){if(e.name==='AbortError')return}}
const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=nome;a.click()}
R.viaturas=async(id)=>{const vs=await viaturas();const v=vs.find(x=>x.id===id)||{id:'',nome:'',placa:'',tipo:'Ambulância de apoio',condutor:'',obs:''};
$('#app').innerHTML=`<h2>Viaturas</h2><a class="btn out" href="#equipe">◀ Voltar à equipe</a><div class="card"><b>${v.id?'Editar viatura':'Nova viatura'}</b><br><label>Nome / identificação</label><input id="vNome" value="${esc(v.nome)}" placeholder="Ex.: Ambulância 01"><label>Placa</label><input id="vPlaca" value="${esc(v.placa)}"><label>Tipo</label><input id="vTipo" value="${esc(v.tipo)}"><label>Equipe / condutor (opcional)</label><input id="vCond" value="${esc(v.condutor)}"><label>Observações</label><textarea id="vObs" rows="2">${esc(v.obs)}</textarea><button class="btn" onclick="salvarV('${v.id}')">Salvar viatura</button>${v.id?`<button class="btn out" onclick="if(confirm('Remover esta viatura?')){del('viaturas','${v.id}').then(()=>location.hash='#viaturas')}">Remover</button>`:''}</div>
<h3>Viaturas cadastradas (${vs.length})</h3>${vs.map(x=>`<a class="card" style="display:block;text-decoration:none;color:inherit" href="#viaturas/${x.id}"><b>🚑 ${esc(x.nome)}</b><div class="muted">${esc(x.tipo)} · Placa: ${esc(x.placa)||'—'} · Condutor: ${esc(x.condutor)||'—'}${x.obs?'<br>'+esc(x.obs):''}</div></a>`).join('')||'<div class="card muted">Nenhuma viatura cadastrada.</div>'}`};
window.salvarV=async id=>{const nome=$('#vNome').value.trim();if(!nome)return alert('Informe o nome da viatura.');await put('viaturas',{id:id||uid(),nome,placa:$('#vPlaca').value,tipo:$('#vTipo').value||'Ambulância de apoio',condutor:$('#vCond').value,obs:$('#vObs').value});location.hash='#viaturas';go()};
R.diarias=async m=>{m=m||mesAtual();const ds=await diariasMes(m);const vs=await viaturas();const VV=Object.fromEntries(vs.map(v=>[v.id,v]));
$('#app').innerHTML=`<h2>Diárias de ambulância</h2><datalist id="lpolos">${POLOS.map(p=>`<option value="${p}">`).join('')}</datalist><div class="grid"><a class="btn out" href="#diarias/${addMes(m,-1)}">◀ Anterior</a><a class="btn out" href="#diarias/${addMes(m,1)}">Próximo ▶</a></div><h3>${mesNome(m)} – ${ds.length} diária(s)</h3>
<div class="card"><b>Nova diária – Ambulância de apoio</b><br><label class="muted">Data</label><input type="date" id="dData" value="${m}-01"><div class="row2"><div><label class="muted">Início</label><input type="time" id="dIni" value="08:00"></div><div><label class="muted">Fim</label><input type="time" id="dFim" value="18:00"></div></div><label class="muted">Evento</label><input id="dNome" placeholder="Ex.: Conferência de jovens"><label class="muted">Local (polo ou texto livre)</label><input list="lpolos" id="dLocal" value="${esc(cfg.polo)}"><label class="muted">Viatura</label><select id="dVia"><option value="">— selecione a viatura —</option>${vs.map(v=>`<option value="${v.id}">${esc(v.nome)}${v.placa?' – '+esc(v.placa):''}</option>`).join('')}</select>${vs.length?'':'<div class="muted">Cadastre a viatura em Equipe › Viaturas.</div>'}<label class="muted">Equipe</label><input id="dEq" placeholder="Nomes da equipe da ambulância"><label class="muted">Observações</label><textarea id="dObs" rows="2"></textarea><button class="btn" onclick="novaDiaria()">➕ Agendar diária</button></div>
${ds.map(d=>{const[s,t]=d.concluido?['concluida','Realizada']:['pendente','Agendada'];return`<div class="card"><div class="polo"><div><b>🚑 ${esc(d.nome)} – ${fmt(d.data)}</b><div class="muted">${d.hora}–${d.horaFim||'?'} · ${esc(d.polo)}<br>Viatura: ${esc(vNome(VV,d.viatura))} · Equipe: ${esc(d.equipeTxt)||'—'}${d.ocorrencias.length?' · Ocorrências: '+d.ocorrencias.length:''}</div></div><span class="st ${s}">${t}</span></div><a class="btn sec" href="#culto/${d.id}">${d.concluido?'Ver registro':'Abrir registro da diária'}</a><button class="btn out" onclick="abrirPDF('${d.id}')">📄 PDF</button><button class="btn out" onclick="if(confirm('Excluir esta diária?')){del('cultos','${d.id}').then(go)}">Excluir</button></div>`}).join('')}`};
window.novaDiaria=async()=>{const d=$('#dData').value;if(!d)return;const c=novoCulto(d,$('#dIni').value,$('#dNome').value||'Diária de ambulância',$('#dLocal').value||cfg.polo);Object.assign(c,{kind:'diaria',horaFim:$('#dFim').value,viatura:$('#dVia').value,equipeTxt:$('#dEq').value,obs:$('#dObs').value});await put('cultos',c);go()};
const mapE=async()=>Object.fromEntries((await equipe()).map(p=>[p.id,p]));
window.pdfCulto=async c=>{const doc=pdfBase(c.kind==='diaria'?'Diária de ambulância':'Relatório do culto','Bombeiros civis nos cultos · PIB Curitiba');await corpoCulto(doc,c,await mapE());rodape(doc);await compartilhar(doc,`Relatorio_culto_${c.data}_${c.hora.replace(':','h')}.pdf`)};
window.pdfMes=async m=>{const cs=await cultosMes(m);const E=await mapE();const doc=pdfBase('Relatório mensal',mesNome(m)+' · Bombeiros civis nos cultos · PIB Curitiba');
const at=cs.filter(c=>c.concluido);const hs=at.reduce((s,c)=>s+horas(c),0);const oc=cs.flatMap(c=>c.ocorrencias);
const ds=await diariasMes(m);const dr=ds.filter(d=>d.concluido);const VV=await mapV();secao(doc,'RESUMO');linha(doc,`Cultos escalados: ${cs.length}   Cultos atendidos: ${at.length}   Horas de serviço: ${hfmt(hs)}`,{bold:true});const hp=at.reduce((s,c)=>s+horas(c)*(3+(c.bri||[]).filter(Boolean).length),0);linha(doc,`Horas-profissional (2 BC + 1 seg. + brigadistas): ${hfmt(hp)}   Ocorrências: ${oc.length}   Escalas incompletas: ${cs.filter(c=>!completo(c)).length}`,{bold:true});linha(doc,`Cultos com Ambulância de apoio: ${cs.filter(c=>c.amb).length}   Diárias de ambulância realizadas: ${dr.length} de ${ds.length}   Horas de diárias: ${hfmt(dr.reduce((s,d)=>s+horas(d),0))}`,{bold:true});
secao(doc,'OCORRÊNCIAS POR TIPO');for(const t of TIPOS)linha(doc,`${t}: ${oc.filter(o=>o.tipo===t).length}`);
secao(doc,'CULTOS');for(const c of cs)linha(doc,`${fmt(c.data)} ${c.hora} · ${c.nome} · ${c.polo} · ${c.concluido?'Atendido':'Em aberto'} · ${hfmt(horas(c))} · ocorrências: ${c.ocorrencias.length}`,{size:9,cor:c.concluido?[30,30,30]:RED});
const cont={};for(const c of at)for(const i of[...c.bc,c.seg,...(c.bri||[])])if(i)cont[i]=(cont[i]||0)+1;if(ds.length){secao(doc,'DIÁRIAS DE AMBULÂNCIA');for(const d of ds)linha(doc,`${fmt(d.data)} ${d.hora}–${d.horaFim||'?'} · ${d.nome} · ${d.polo} · ${vNome(VV,d.viatura)} · ${d.concluido?'Realizada':'Em aberto'} · ocorrências: ${d.ocorrencias.length}`,{size:9})}secao(doc,'PARTICIPAÇÃO DA EQUIPE');for(const[i,n]of Object.entries(cont))linha(doc,`${E[i]?E[i].nome:'?'} (${E[i]?FUN[E[i].funcao]:''}): ${n} culto(s)`);
for(const c of cs.filter(c=>c.ocorrencias.length)){doc.addPage();cab(doc);await corpoCulto(doc,c,E)}rodape(doc);await compartilhar(doc,`Relatorio_mensal_${m}.pdf`)};
R.relatorios=async()=>{const all=(await getAll('cultos')).filter(c=>!REMOVIDOS.includes(c.polo)).sort((a,b)=>a.data<b.data?1:-1);
$('#app').innerHTML=`<h2>Relatórios</h2><div class="card"><label>Mês do relatório consolidado</label><input type="month" id="mesR" value="${mesAtual()}"><button class="btn sec" onclick="pdfMes($('#mesR').value)">📄 Relatório mensal consolidado</button><p class="muted">Inclui cultos atendidos, horas, ocorrências por tipo e participação da equipe. No celular, abre o compartilhamento (WhatsApp, e-mail…).</p></div><h3>Por culto</h3>${all.length?all.map(c=>`<div class="card polo"><div><b>${esc(c.nome)} – ${fmt(c.data)}</b><div class="muted">${esc(c.polo)} · ${c.concluido?'Atendido':'Em aberto'} · ${c.ocorrencias.length} ocorrência(s)</div></div><button class="btn sec" style="width:auto;padding:10px" onclick="abrirPDF('${c.id}')">PDF</button></div>`).join(''):'<div class="card muted">Nenhum culto registrado ainda.</div>'}`};
window.abrirPDF=async id=>pdfCulto(await get('cultos',id));
// ---------- proposta ----------
function tabPolos(cls){const A=ativos();if(!A.length)return'<p class="muted">Nenhum polo marcado como atendido.</p>';return`<table class="${cls||''}"><tr><th>Polo</th><th>Cultos</th><th>Diárias/mês</th></tr>${A.map(p=>`<tr><td>${esc(p)}${cfg.polos[p].confirmar?' <small>(a confirmar)</small>':''}</td><td>${cfg.polos[p].cultos.map(t=>DIAS[t.dia].slice(0,3)+' '+(t.hora||'?')).join(' · ')||'—'}</td><td>~${fnum(diaSem(p)*52/12)}</td></tr>`).join('')}<tr><td><b>Total</b></td><td>${porSemana()} cultos por semana</td><td><b>~${fnum(A.reduce((s,p)=>s+diaSem(p),0)*52/12)}</b></td></tr></table>`}
function diaSem(p){return new Set((cfg.polos[p]?.cultos||[]).filter(t=>t.hora).map(t=>t.dia)).size}
R.proposta=async()=>{const pm=porMes();const ms=mesesPiloto();const reais=ms.map(m=>datasModelo(m).length);
$('#app').innerHTML=`<div class="banner"><h2>Proposta – Piloto de 3 meses</h2><p>Bombeiros civis profissionais e segurança descaracterizado nos cultos da PIB Curitiba (sexta a domingo)</p><p>Responsável: ${RESP}</p></div>
<h3>Objetivo</h3><div class="card">Demonstrar, em 3 meses, a qualidade e a eficiência de uma equipe profissional fixa nos cultos: prevenção antes do culto, resposta rápida a emergências e registro de tudo em relatório entregue à liderança.</div>
<h3>Modelo do serviço</h3><div class="card"><b>Por culto: 2 bombeiros civis + 1 segurança descaracterizado + brigadistas profissionais conforme necessidade</b><br><br>🚒 <b>Bombeiros civis</b> (contratados por culto): checklist pré-culto, prevenção e combate a princípio de incêndio, primeiros socorros/DEA, apoio à evacuação.<br><br>🕶️ <b>Segurança descaracterizado</b>: atua sem uniforme, junto à brigada, em situações de emergência e em pequenos conflitos ou perturbações que possam atrapalhar o culto, de forma discreta.<br><br>🚑 <b>Ambulância de apoio</b> (opcional por culto): viatura de suporte posicionada no local durante o culto, para remoção e apoio aos atendimentos.<br><br>🦺 <b>Brigadistas profissionais</b> (opcionais, conforme necessidade – ex.: cultos com grande público ou eventos especiais): reforço na prevenção, primeiros socorros, controle de fluxo e evacuação.</div>
<h3>Diárias de ambulância</h3><div class="card">Além dos cultos, a <b>Ambulância de apoio</b> pode ser contratada por <b>diária</b> para eventos, conferências, acampamentos e atividades especiais da PIB, com equipe, registro de ocorrências e relatório próprio.</div>
<h3>Polos atendidos e cultos por mês</h3><div class="card">${tabPolos()}<p class="muted">Horários conforme o site da PIB; ajustáveis na aba Escala.</p></div>
<h3>Dimensionamento</h3><div class="grid"><div class="card kpi"><b>${porSemana()}</b><small>cultos por semana</small></div><div class="card kpi"><b>~${pm}</b><small>cultos por mês (4 semanas)</small></div><div class="card kpi"><b>~${pm*3}</b><small>cultos no piloto</small></div><div class="card kpi"><b>~${pm*2*3}</b><small>diárias de BC no piloto</small></div></div>
<div class="card"><label>Mês de início do piloto</label><input type="month" value="${cfg.inicio}" onchange="cfg.inicio=this.value;saveCfg();go()"><table>${ms.map((m,i)=>`<tr><td>${mesNome(m)}</td><td>${reais[i]} cultos no calendário</td></tr>`).join('')}</table></div>
<h3>Registro em cada culto</h3><div class="card">✓ Check-in e check-out da equipe<br>✓ Checklist pré-culto: ${CHECK.join(', ').toLowerCase()}<br>✓ Público estimado<br>✓ Ocorrências com tipo, hora, ação tomada e encaminhamento<br>✓ Fotos e vídeos</div>
<h3>Entregas</h3><div class="card">✓ Relatório por culto (PDF)<br>✓ Relatório mensal consolidado: cultos atendidos, horas e ocorrências por tipo<br>✓ Relatório final do piloto com os indicadores dos 3 meses</div>
<h3>Investimento</h3><div class="card"><b>A definir.</b></div>`};
// ---------- ajustes / backup ----------
R.config=async()=>{$('#app').innerHTML=`<h2>Ajustes</h2><div class="card"><b>Versão do aplicativo: ${VER}</b><p class="muted">Se alguma tela não aparecer ou o app parecer desatualizado, toque abaixo. Os dados salvos (cultos, equipe, viaturas, fotos) NÃO são apagados.</p><button class="btn sec" onclick="forcarAtualizacao()">🔄 Forçar atualização</button></div><h3>Backup</h3><div class="card"><p class="muted">Os dados ficam só neste aparelho. Exporte o backup com frequência (ex.: depois de cada fim de semana) e guarde no Google Drive ou no WhatsApp.</p><button class="btn sec" onclick="exportar()">⬇ Exportar backup (.zip)</button><label class="btn out">⬆ Importar backup<input type="file" accept=".zip" style="display:none" onchange="importar(this.files[0])"></label></div>
<h3>Instalar no celular</h3><div class="card muted"><b>iPhone:</b> no Safari, toque em Compartilhar › Adicionar à Tela de Início.<br><b>Android:</b> no Chrome, menu ⋮ › Instalar app.</div>
<div class="card muted"><b>Limitação:</b> sem sincronização na nuvem – cada celular guarda seus próprios dados.</div>`};
window.forcarAtualizacao=async()=>{try{if('serviceWorker'in navigator)for(const r of await navigator.serviceWorker.getRegistrations())await r.unregister();if(window.caches)for(const k of await caches.keys())await caches.delete(k)}catch(e){}location.replace(location.pathname+'?atualizado='+Date.now()+location.hash)};
window.exportar=async()=>{const z=new JSZip();const ms=await getAll('midias');z.file('dados.json',JSON.stringify({versao:1,cfg,equipe:await getAll('equipe'),viaturas:await getAll('viaturas'),cultos:await getAll('cultos'),midias:ms.map(m=>({id:m.id,tipo:m.tipo,nome:m.nome,quando:m.quando}))}));ms.forEach(m=>z.file('midias/'+m.id,m.blob));
const b=await z.generateAsync({type:'blob'});window._ultimoZIP=b;const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=`backup-bombeiros-cultos-${ymd(new Date())}.zip`;a.click()};
window.importar=async f=>{if(!f)return;const z=await JSZip.loadAsync(f);const d=JSON.parse(await z.file('dados.json').async('string'));for(const m of d.midias){const fz=z.file('midias/'+m.id);if(fz)await put('midias',{...m,blob:new Blob([await fz.async('arraybuffer')],{type:m.tipo})})}for(const p of d.equipe)await put('equipe',p);for(const v of d.viaturas||[])await put('viaturas',v);for(const c of d.cultos)await put('cultos',c);if(d.cfg){cfg=d.cfg;saveCfg()}alert(`Backup importado: ${d.equipe.length} profissional(is), ${d.cultos.length} culto(s).`);go()};
// ---------- preços ----------
const defPrecos=()=>({bc:280,seg:250,bri:250,nBri:0,amb:810,nAmb:0,cbc:180,cseg:180,cbri:0,camb:500,todos:true,base:'media',mes:''});
function precos(){const d=defPrecos();const p=Object.assign(d,cfg.precos||{});for(const k of['bc','seg','bri','nBri','amb','nAmb','cbc','cseg','cbri','camb'])p[k]=Math.max(0,+p[k]||0);cfg.precos=p;return p}
const brl=v=>'R$ '+v.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
const fnum=v=>(Math.round(v*100)/100).toLocaleString('pt-BR',{maximumFractionDigits:2});
function semPolo(p){return(cfg.polos[p]?.cultos||[]).filter(t=>t.hora).length}
function mesPolo(p,m){let n=0;const d=pd(m+'-01'),mm=d.getMonth();const c=(cfg.polos[p]?.cultos||[]).filter(t=>t.hora);while(d.getMonth()===mm){n+=c.filter(t=>t.dia===d.getDay()).length;d.setDate(d.getDate()+1)}return n}
const LIMQ={bc:4,seg:2,bri:4};
function defSel(p){return{bc:p==='PIB Batel'?2:1,seg:p==='PIB Batel'?1:0,bri:0,amb:false}}
const clampS=o=>({bc:Math.min(4,Math.max(0,+o.bc||0)),seg:Math.min(2,Math.max(0,+o.seg||0)),bri:Math.min(4,Math.max(0,+o.bri||0)),amb:!!o.amb,...(o.on===undefined?{}:{on:!!o.on})});
function migraSelD(){if(cfg.selD)return;cfg.selD={};for(const[p,m]of Object.entries(cfg.sel||{})){const cul=(cfg.polos[p]||{}).cultos||[];for(const[i,o]of Object.entries(m||{})){const t=cul[+i];if(!t||!o)continue;const c=clampS(o),a=cfg.selD[p]=cfg.selD[p]||{};const x=a[t.dia];a[t.dia]=x?{bc:Math.max(x.bc,c.bc),seg:Math.max(x.seg,c.seg),bri:Math.max(x.bri,c.bri),amb:x.amb||c.amb}:c}}saveCfg()}
function getSel(p,dia){migraSelD();const o=(cfg.selD[p]||{})[dia];return o&&typeof o==='object'?clampS(o):defSel(p)}
function getSelOld(p,i){cfg.sel=cfg.sel||{};const o=(cfg.sel[p]||{})[i];const d=defSel(p);if(!o||typeof o!=='object')return d;return{bc:Math.min(4,Math.max(0,+o.bc||0)),seg:Math.min(2,Math.max(0,+o.seg||0)),bri:Math.min(4,Math.max(0,+o.bri||0)),amb:!!o.amb}}
function putSel(p,dia,v){migraSelD();(cfg.selD[p]=cfg.selD[p]||{})[dia]=v}
function nDiaMes(dia,m){let n=0;const d=pd(m+'-01'),mm=d.getMonth();while(d.getMonth()===mm){if(d.getDay()===dia)n++;d.setDate(d.getDate()+1)}return n}
function calcPrecos(){const P=precos();const mes=P.mes||mesAtual();const lista=Object.keys(cfg.polos).filter(p=>P.todos||cfg.polos[p].ativo);
const linhas=lista.map(p=>{const bat=p==='PIB Batel';const hs=(cfg.polos[p].cultos||[]).filter(t=>t.hora);const V=!hs.length;const dias=[5,6,0,...[1,2,3,4].filter(d=>hs.some(t=>t.dia===d))];const cul=dias.map(dia=>{const dc=hs.filter(t=>t.dia===dia).sort((a,b)=>a.hora<b.hora?-1:1);const t={dia,hora:dc.map(x=>x.hora).join(', '),nome:dc.map(x=>x.nome).join(' · ')},i=dia;const s=getSel(p,i);const on=s.on===undefined?true:s.on;const VD=!dc.length;const pc=!on?0:s.bc*P.bc+s.seg*P.seg+s.bri*P.bri+(s.amb?P.amb:0);const cc=!on?0:s.bc*P.cbc+s.seg*P.cseg+s.bri*P.cbri+(s.amb?P.camb:0);const cm=!on?0:P.base==='media'?52/12:nDiaMes(t.dia,mes);return{i,t,s,on,V:VD,pc,cc,cm,n:dc.length,tot:pc*cm,custo:cc*cm}});
const cm=cul.reduce((a,c)=>a+c.cm,0),tot=cul.reduce((a,c)=>a+c.tot,0),custo=cul.reduce((a,c)=>a+c.custo,0);return{p,bat,cul,V,sem:cul.filter(c=>c.on).length,nc:hs.length,cm,pc:cm?tot/cm:0,tot,custo,conf:cfg.polos[p].confirmar}});
const sb=linhas.filter(l=>l.bat),so=linhas.filter(l=>!l.bat);const S=a=>a.reduce((s,l)=>s+l.tot,0),SC=a=>a.reduce((s,l)=>s+l.custo,0);
const amb=P.nAmb*P.amb,cAmb=P.nAmb*P.camb;const tot=S(linhas)+amb,custo=SC(linhas)+cAmb;
return{P,mes,linhas,batel:S(sb),outros:S(so),amb,tot,custo,lucro:tot-custo,piloto:tot*3,lucro3:(tot-custo)*3,cultos:linhas.reduce((s,l)=>s+l.cm,0)}}
function selTxt(s){return[s.bc?s.bc+' BC':'',s.seg?s.seg+' seg.':'',s.bri?s.bri+' brig.':'',s.amb?'ambulância':''].filter(Boolean).join(' + ')||'nada'}
function quadroHTML(k){const st=(p,i,f,v)=>{const q=esc(p).replace(/'/g,"\\'");return`<span class="stp"><button onclick="qSel('${q}',${i},'${f}',-1)">−</button><b id="q-${f}-${i}-${k.linhas.findIndex(l=>l.p===p)}">${v}</b><button onclick="qSel('${q}',${i},'${f}',1)">+</button></span>`};
return k.linhas.map((l,li)=>{const q=esc(l.p).replace(/'/g,"\\'");return`<details class="card qd" ${l.bat?'open':''}><summary><b>${esc(l.p)}</b> <span class="muted">${l.sem} diária(s)/sem. · ${l.nc} culto(s)</span><span class="qt" id="qt-${li}">${brl(l.tot)}</span></summary>
${l.V?'<div class="warn">⚠ Horário a confirmar – padrão sexta, sábado e domingo; desmarque os dias que não deseja atender.</div>':''}${l.cul.length?l.cul.map(c=>`<div class="qc" style="${c.on?'':'opacity:.55'}"><div class="qh"><label class="chk" style="border:0;padding:0"><input type="checkbox" ${c.on?'checked':''} onchange="qOn('${q}',${c.i},this.checked)"><b>📅 ${DIAS[c.t.dia][0].toUpperCase()+DIAS[c.t.dia].slice(1)} – diária</b></label> <span class="muted">${c.V?'horário a confirmar':c.n+' culto(s): '+c.t.hora+'<br>'+esc(c.t.nome)}</span><span class="qv" id="qv-${li}-${c.i}">${brl(c.pc)}/diária</span></div>
<div class="qg"><label>🚒 Bombeiro civil ${st(l.p,c.i,'bc',c.s.bc)}</label><label>🕶️ Segurança ${st(l.p,c.i,'seg',c.s.seg)}</label><label>🦺 Brigadista ${st(l.p,c.i,'bri',c.s.bri)}</label><label class="chk" style="border:0"><input type="checkbox" ${c.s.amb?'checked':''} onchange="qAmb('${q}',${c.i},this.checked)">🚑 Ambulância (${brl(k.P.amb)}/diária)</label></div></div>`).join('')+`<div class="row2"><button class="btn out" style="padding:9px;font-size:13px" onclick="qPolo('${q}',${l.cul[0].i})">Aplicar 1º dia a todos os dias do polo</button><button class="btn out" style="padding:9px;font-size:13px" onclick="qPadrao('${q}')">Padrão do polo</button></div>`
:`<p class="muted">⚠ Horário a confirmar – 0 cultos. Cadastre os horários na aba Escala para calcular.</p>`}</details>`}).join('')}
window.qSel=(p,i,f,d)=>{const s=getSel(p,i);s[f]=Math.min(LIMQ[f],Math.max(0,s[f]+d));putSel(p,i,s);saveCfg();qAtualiza()};
window.qOn=(p,i,v)=>{const s=getSel(p,i);s.on=v;putSel(p,i,s);saveCfg();go()};
window.qAmb=(p,i,v)=>{const s=getSel(p,i);s.amb=v;putSel(p,i,s);saveCfg();qAtualiza()};
window.qPolo=(p,i0)=>{const s=getSel(p,i0);(()=>{const d=[...new Set((cfg.polos[p].cultos||[]).filter(t=>t.hora).map(t=>t.dia))];return[...new Set([5,6,0,...d])]})().forEach(d=>putSel(p,d,{...s}));saveCfg();go()};
window.qPadrao=p=>{migraSelD();delete cfg.selD[p];saveCfg();go()};
window.qTodos=()=>{const p=$('#qtP').value;const s={bc:+$('#qtBC').value,seg:+$('#qtSeg').value,bri:+$('#qtBri').value,amb:$('#qtAmb').checked};for(const l of calcPrecos().linhas)for(const c of l.cul)putSel(l.p,c.i,p==='batel'&&!l.bat||p==='outros'&&l.bat?getSel(l.p,c.i):{...s,on:c.on});saveCfg();go()};
window.qAtualiza=()=>{const k=calcPrecos();k.linhas.forEach((l,li)=>{const e=$('#qt-'+li);if(e)e.textContent=brl(l.tot);l.cul.forEach(c=>{const v=$(`#qv-${li}-${c.i}`);if(v)v.textContent=brl(c.pc)+'/diária';for(const f of['bc','seg','bri']){const b=$(`#q-${f}-${c.i}-${li}`);if(b)b.textContent=c.s[f]}})});
const set=(id,t)=>{const e=$(id);if(e)e.textContent=t};set('#sbTot',brl(k.tot));set('#sbPil',brl(k.piloto));set('#sbLuc',brl(k.lucro)+' ('+(k.tot?Math.round(k.lucro/k.tot*100):0)+'%)');set('#rsBat',brl(k.batel));set('#rsOut',brl(k.outros));set('#rsAmb',brl(k.amb));set('#rsTot',brl(k.tot));set('#rsPil',brl(k.piloto));set('#rsCus',brl(k.custo));set('#rsLuc',brl(k.lucro));set('#rsLuc3',brl(k.lucro3))};
R.precos=async()=>{const k=calcPrecos(),P=k.P;const inp=(id,lab,step)=>`<div><label class="muted">${lab}</label><input type="number" min="0" step="${step||'0.01'}" value="${P[id]}" onchange="cfg.precos.${id}=+this.value;saveCfg();go()"></div>`;
$('#app').innerHTML=`<h2>Preços – cálculo mensal</h2>
<div class="card"><b>Regra de equipe</b><p class="muted">PIB Batel: <b>2 bombeiros civis + 1 segurança</b> por diária (dia de culto). Demais polos: <b>1 bombeiro civil</b> por diária. Esse é o padrão; ajuste cada culto no quadro de marcação abaixo.</p>
<div class="row2">${inp('bc','Bombeiro civil (R$/diária)')}${inp('seg','Segurança (R$/diária)')}</div><div class="row2">${inp('bri','Brigadista (R$/diária)')}${inp('amb','Ambulância (R$/diária)')}</div>
<label class="chk"><input type="checkbox" ${P.todos?'checked':''} onchange="cfg.precos.todos=this.checked;saveCfg();go()">Incluir todos os polos (desmarque para só os polos atendidos na Escala)</label>
<label class="muted">Base de cálculo de diárias/mês</label><select onchange="cfg.precos.base=this.value;saveCfg();go()"><option value="media" ${P.base==='media'?'selected':''}>Média mensal (diárias/semana × 4,33)</option><option value="mes" ${P.base==='mes'?'selected':''}>Contagem real do mês escolhido</option></select>${P.base==='mes'?`<input type="month" value="${k.mes}" onchange="cfg.precos.mes=this.value;saveCfg();go()">`:''}</div>
<h3>📋 Quadro de marcação – o que deseja em cada dia de culto (diária)</h3><p class="muted">Valores <b>por diária</b>: padrão sexta, sábado e domingo em todos os polos (3 diárias/semana); cada dia é uma diária, mesmo com vários cultos. ${P.base==='media'?'Diárias/mês = diárias por semana × 4,33':'Contagem real de '+mesNome(k.mes)}. O total atualiza na hora.</p>
<div class="card"><b>Aplicar a todos</b><div class="row2"><label class="muted">Bombeiros<select id="qtBC">${[0,1,2,3,4].map(n=>`<option ${n===1?'selected':''}>${n}</option>`).join('')}</select></label><label class="muted">Seguranças<select id="qtSeg">${[0,1,2].map(n=>`<option>${n}</option>`).join('')}</select></label></div><div class="row2"><label class="muted">Brigadistas<select id="qtBri">${[0,1,2,3,4].map(n=>`<option>${n}</option>`).join('')}</select></label><label class="muted">Em quais polos<select id="qtP"><option value="todos">Todos</option><option value="batel">Só PIB Batel</option><option value="outros">Só demais polos</option></select></label></div><label class="chk" style="border:0"><input type="checkbox" id="qtAmb">🚑 Ambulância em todos</label><button class="btn sec" onclick="qTodos()">Aplicar a todas as diárias</button></div>
${quadroHTML(k)}
<h3>🚑 Ambulância de apoio (separado)</h3><div class="card"><p class="muted">${brl(P.amb)} por diária · local e horários a definir.</p><div class="row2">${inp('amb','Valor da diária (R$)')}${inp('nAmb','Diárias por mês','1')}</div><b>Ambulância no mês: ${brl(k.amb)}</b></div>
<h3>Resumo mensal</h3><div class="card"><table><tr><td>Subtotal PIB Batel</td><td><b id="rsBat">${brl(k.batel)}</b></td></tr><tr><td>Subtotal demais polos</td><td><b id="rsOut">${brl(k.outros)}</b></td></tr><tr><td>Ambulância de apoio</td><td><b id="rsAmb">${brl(k.amb)}</b></td></tr><tr><td><b>TOTAL GERAL MENSAL</b></td><td><b id="rsTot" style="color:var(--red);font-size:18px">${brl(k.tot)}</b></td></tr><tr><td><b>Piloto de 3 meses</b></td><td><b id="rsPil">${brl(k.piloto)}</b></td></tr></table><p class="muted">${fnum(k.cultos)} diárias/mês no cálculo. Polos "a confirmar" sem horários cadastrados entram com 0 cultos até você preencher na aba Escala.</p></div>
<h3>Custos e lucro estimado (opcional, interno)</h3><div class="card"><div class="row2">${inp('cbc','Custo bombeiro civil')}${inp('cseg','Custo segurança')}</div><div class="row2">${inp('cbri','Custo brigadista')}${inp('camb','Custo diária ambulância')}</div><table><tr><td>Custo mensal</td><td id="rsCus">${brl(k.custo)}</td></tr><tr><td><b>Lucro estimado mensal</b></td><td><b id="rsLuc" style="color:var(--ok)">${brl(k.lucro)}</b> (${k.tot?Math.round(k.lucro/k.tot*100):0}%)</td></tr><tr><td>Lucro estimado no piloto (3 meses)</td><td><b id="rsLuc3">${brl(k.lucro3)}</b></td></tr></table></div>
<button class="btn sec" onclick="pdfPrecos(false)">📄 PDF da tabela de preços (para o cliente)</button><button class="btn out" onclick="pdfPrecos(true)">📄 PDF interno (com custos e lucro)</button><button class="btn out" onclick="if(confirm('Voltar aos valores e marcações padrão?')){cfg.precos=defPrecos();cfg.sel={};cfg.selD={};saveCfg();go()}">Restaurar valores padrão</button><div style="height:90px"></div><div class="sbarP"><div><small>Total mensal</small><b id="sbTot">${brl(k.tot)}</b></div><div><small>Piloto 3 meses</small><b id="sbPil">${brl(k.piloto)}</b></div><div class="${P.verLucro?'':'hidden'}" id="sbLW"><small>Lucro estimado</small><b id="sbLuc" style="color:#7ee2a0">${brl(k.lucro)} (${k.tot?Math.round(k.lucro/k.tot*100):0}%)</b></div><label class="sbT"><input type="checkbox" ${P.verLucro?'checked':''} onchange="cfg.precos.verLucro=this.checked;saveCfg();$('#sbLW').classList.toggle('hidden',!this.checked)"> lucro</label></div>`};
window.pdfPrecos=async interno=>{const k=calcPrecos(),P=k.P;const doc=pdfBase('Tabela de preços',(P.base==='media'?'Média mensal (4,33 semanas)':'Base: '+mesNome(k.mes))+' · Bombeiros civis nos cultos · PIB Curitiba');
secao(doc,'REGRA DE EQUIPE');linha(doc,'Valores POR DIÁRIA (cada dia de culto do polo = 1 diária, mesmo com vários cultos no dia). Equipe conforme marcação (padrão: PIB Batel 2 bombeiros civis + 1 segurança; demais polos 1 bombeiro civil).');linha(doc,`Valores: bombeiro civil ${brl(P.bc)}/diária · segurança ${brl(P.seg)}/diária · brigadista ${brl(P.bri)}/diária · ambulância ${brl(P.amb)}/diária`);
secao(doc,'POR POLO E DIA DE CULTO');for(const l of k.linhas){linha(doc,`${l.p}${l.V?' (horário a confirmar)':''}: ${fnum(l.cm)} diárias/mês = ${brl(l.tot)}`,{bold:true,size:10});for(const c of l.cul.filter(c=>c.on))linha(doc,`${DIAS[c.t.dia]} (${c.V?'horário a confirmar':'cultos '+c.t.hora}): ${selTxt(c.s)} · ${brl(c.pc)}/diária × ${fnum(c.cm)} = ${brl(c.tot)}`,{size:8.5,x:16,w:182})}
secao(doc,'AMBULÂNCIA DE APOIO');linha(doc,`${brl(P.amb)} por diária – local e horários a definir. ${P.nAmb} diária(s)/mês = ${brl(k.amb)}`);
secao(doc,'RESUMO MENSAL');linha(doc,'Subtotal PIB Batel: '+brl(k.batel),{bold:true});linha(doc,'Subtotal demais polos: '+brl(k.outros),{bold:true});linha(doc,'Ambulância de apoio: '+brl(k.amb),{bold:true});linha(doc,'TOTAL GERAL MENSAL: '+brl(k.tot),{bold:true,size:13,cor:RED});linha(doc,'Piloto de 3 meses: '+brl(k.piloto),{bold:true,size:12,cor:NAVY});
if(interno){secao(doc,'INTERNO – CUSTOS E LUCRO');linha(doc,`Custos: BC ${brl(P.cbc)} · seg. ${brl(P.cseg)} · brig. ${brl(P.cbri)} · ambulância ${brl(P.camb)}/diária`);linha(doc,'Custo mensal: '+brl(k.custo));linha(doc,'Lucro estimado mensal: '+brl(k.lucro),{bold:true});linha(doc,'Lucro estimado no piloto: '+brl(k.lucro3),{bold:true})}
rodape(doc);await compartilhar(doc,`Tabela_precos${interno?'_interna':''}_${ymd(new Date())}.pdf`)};
// ---------- apresentação ----------
let SL=0,SLN=0;
R.apresentacao=async()=>{const all=await getAll('cultos');const cs=all.filter(c=>c.kind!=='diaria'),ds=all.filter(c=>c.kind==='diaria');const at=cs.filter(c=>c.concluido),dr=ds.filter(d=>d.concluido);
const oc=[...at,...dr].reduce((s,c)=>s+c.ocorrencias.length,0),hs=[...at,...dr].reduce((s,c)=>s+horas(c),0);const pm=porMes();
const ind=at.length||dr.length?`<div class="sgrid"><div class="sk"><b>${at.length}</b><small>cultos atendidos</small></div><div class="sk"><b>${oc}</b><small>ocorrências registradas</small></div><div class="sk"><b>${hfmt(hs)}</b><small>horas de serviço</small></div><div class="sk"><b>${dr.length}</b><small>diárias de ambulância</small></div></div>`:`<div class="sbox">📈 Os indicadores aparecem aqui automaticamente assim que os primeiros cultos forem atendidos e registrados no aplicativo.</div><div class="sgrid"><div class="sk"><b>0</b><small>cultos atendidos</small></div><div class="sk"><b>0</b><small>ocorrências</small></div><div class="sk"><b>0 h</b><small>horas de serviço</small></div></div>`;
const S=[
`<div class="scapa"><div class="slogo">🚒</div><p class="sk2">NR Treinamentos e Assessoria</p><h1>Serviço de Segurança e Proteção nos Cultos</h1><h2>PIB Curitiba</h2><p>Responsável: ${RESP}</p></div>`,
`<h1>O desafio</h1><ul><li>Cultos de sexta a domingo com <b>grande público</b>, crianças e idosos</li><li>Risco de <b>mal súbito</b>, quedas e emergências médicas</li><li>Risco de <b>princípio de incêndio</b> e necessidade de evacuação rápida</li><li><b>Pequenos conflitos</b> e perturbações que atrapalham o culto</li><li>Exigências de segurança contra incêndio e pânico (NPT)</li></ul>`,
`<h1>Nossa equipe por culto</h1><div class="sgrid"><div class="sk"><b>2</b><small>bombeiros civis</small></div><div class="sk"><b>1</b><small>segurança descaracterizado</small></div><div class="sk"><b>+</b><small>brigadistas profissionais conforme necessidade</small></div></div><p class="sc">Equipe profissional, certificada e identificada no aplicativo.</p>`,
`<h1>O papel de cada função</h1><div class="scards"><div><b>🚒 Bombeiro civil</b>Checklist pré-culto, prevenção e combate a princípio de incêndio, primeiros socorros/DEA, evacuação.</div><div><b>🕶️ Segurança descaracterizado</b>Atua sem uniforme, de forma discreta, em situações de brigada e pequenos conflitos.</div><div><b>🦺 Brigadista profissional</b>Reforço em cultos de grande público e eventos especiais: fluxo, prevenção e apoio.</div></div>`,
`<h1>🚑 Ambulância de apoio</h1><div class="scards"><div><b>Por culto (opcional)</b>Viatura posicionada no local durante o culto, para remoção e apoio aos atendimentos.</div><div><b>Diárias para eventos</b>Conferências, acampamentos e atividades especiais, com equipe, registro e relatório próprio.</div></div>`,
`<h1>Polos e cultos atendidos</h1>${tabPolos('stab')}<div class="sgrid"><div class="sk"><b>${porSemana()}</b><small>cultos por semana</small></div><div class="sk"><b>~${pm}</b><small>cultos por mês</small></div><div class="sk"><b>~${pm*3}</b><small>cultos no piloto</small></div></div>`,
`<h1>Como funciona o aplicativo</h1><div class="scards"><div><b>✅ Checklist pré-culto</b>Rotas de fuga, extintores, iluminação de emergência, saídas, kit/DEA e rádio.</div><div><b>📷 Ocorrências</b>Tipo, hora, ação tomada e encaminhamento, com fotos e vídeos.</div><div><b>📄 Relatórios em PDF</b>Por culto e mensal consolidado, enviados pelo WhatsApp ou e-mail.</div></div>`,
`<h1>Indicadores ao vivo</h1>${ind}`,
`<h1>Piloto de 3 meses</h1><ul><li>Início: <b>${mesNome(cfg.inicio)}</b></li><li>Cerca de <b>${pm*3} cultos</b> com equipe completa</li><li>Relatório por culto e relatório mensal à liderança</li><li>Ao final, a PIB decide com base em <b>indicadores reais</b></li></ul>`,
`<h1>Investimento</h1><div class="sbig">A definir</div><p class="sc">Valores apresentados em proposta comercial à parte: valores por diária (dia de culto) para bombeiros civis, segurança, brigadistas e ambulância de apoio.</p>`,
`<div class="scapa"><div class="slogo">🙏</div><h1>Obrigado!</h1><p class="sk2">NR Treinamentos e Assessoria</p><p>${RESP}</p><p class="sc">Vamos cuidar juntos de quem vem à PIB.</p></div>`];
const BG=['templo-lotado','galerias','palco','coral-natal'];const BGS=[0,1,3,2,0,1,2,3,1,2,0];SLN=S.length;SL=Math.min(SL,SLN-1);
$('#app').innerHTML=`<div id="apr" class="apr"><div class="sbar"><span>NR Treinamentos e Assessoria</span><span><button onclick="telaCheia()">⛶ Tela cheia</button><button onclick="sairApr()">✕ Sair</button></span></div><div class="strack" id="strack">${S.map((x,i)=>`<section class="slide" style="background-image:linear-gradient(180deg,rgba(11,31,58,.80),rgba(6,18,42,.93)),url(img/${BG[BGS[i]]}.jpg)"><div class="sin">${x}</div></section>`).join('')}</div><button class="snav l" onclick="slide(-1)">‹</button><button class="snav r" onclick="slide(1)">›</button><div class="sdots">${S.map((_,i)=>`<i onclick="slide(${i}-SL)"></i>`).join('')}</div></div>`;
document.body.classList.add('modoapr');slide(0);
const el=$('#apr');let x0=null;el.ontouchstart=e=>x0=e.touches[0].clientX;el.ontouchend=e=>{if(x0==null)return;const d=e.changedTouches[0].clientX-x0;if(Math.abs(d)>40)slide(d<0?1:-1);x0=null};
$('#strack').onclick=e=>{slide(e.clientX>innerWidth/2?1:-1)}};
window.slide=d=>{SL=Math.max(0,Math.min(SLN-1,SL+d));const t=$('#strack');if(!t)return;t.style.transform=`translateX(-${SL*100}%)`;document.querySelectorAll('.sdots i').forEach((x,i)=>x.classList.toggle('on',i===SL))};
window.telaCheia=()=>{const e=document.documentElement;if(document.fullscreenElement)document.exitFullscreen();else(e.requestFullscreen||e.webkitRequestFullscreen||(()=>{})).call(e)};
window.sairApr=()=>{if(document.fullscreenElement)document.exitFullscreen();location.hash='#painel'};
document.addEventListener('keydown',e=>{if(!$('#apr'))return;if(['ArrowRight','PageDown',' '].includes(e.key))slide(1);if(['ArrowLeft','PageUp'].includes(e.key))slide(-1);if(e.key==='Escape')sairApr()});
window.addEventListener('hashchange',()=>{if(!location.hash.startsWith('#apresentacao'))document.body.classList.remove('modoapr')});
if('serviceWorker'in navigator){const tinha=!!navigator.serviceWorker.controller;let rec=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(tinha&&!rec){rec=true;location.reload()}});
navigator.serviceWorker.register('sw.js',{updateViaCache:'none'}).then(reg=>{const up=()=>reg.update().catch(()=>{});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')up()});setInterval(up,30*60*1000);if(reg.waiting)reg.waiting.postMessage('skipWaiting')}).catch(()=>{})}
document.querySelector('.brand small').textContent='Bombeiros Civis nos Cultos · '+VER;go();
